// Start screen: the PM's first choices drawn as the three M stripes flowing down like a Sankey
// diagram. At each choice the stripes fan out to the options; the one the PM picks pulls them
// back together and they flow on through it to the next choice, the brief and the Start button.
// Motion follows Apple's fluid-interface rules: critically damped springs that start from the
// current on-screen value, so every change can be redirected mid-flight.

const N = 3; // stripes: light blue, dark blue, red
const W = 10; // width of one stripe (px); they touch, like the M stripes
const FORK = 96; // vertical run in which the stripes curve into a row (= the row's top padding)
const RESPONSE = 0.45; // spring response in seconds (Apple: 0.3–0.4 for UI moves, a bit calmer here)
const DAMPING = 1; // critically damped: no overshoot
const DEFAULT_GOAL = "Which customer requirements should the successor generation fulfil, "
  + "based on what customers say about the current model?";
const UPLOAD = "__upload";

const STAGES = [
  { key: "vehicle", title: "Vehicle", hint: "Whose successor are we planning?", options: [
    { value: "BMW 1 Series", label: "1 Series", sub: "F70" },
    { value: "BMW 5 Series", label: "5 Series", sub: "G60" },
    { value: "BMW 7 Series", label: "7 Series", sub: "G70" }] },
  { key: "market", title: "Market", hint: "Where should it win?", options: [
    { value: "United States", label: "USA", sub: "US" },
    { value: "Europe", label: "Europe", sub: "EU" },
    { value: "China", label: "China", sub: "CN" }] },
  { key: "sources", title: "Sources", hint: "What the agent may read. Pick one or more.", multi: true, options: [] },
  { key: "brief", title: "Brief", hint: "The question the agent works on. Edit it if you like." },
  { key: "launch", title: "Start", hint: "Every step is recorded under your name." },
];

const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
const reducedMotion = () => matchMedia("(prefers-reduced-motion: reduce)").matches;

/**
 * root: the empty <section id="start">. loadDatasets: () => Promise<[{name, rows}]>.
 * onStart({vehicle, market, datasets, file, goal, name, steps}): does the API work; throw to stay.
 */
export function createStart(root, { loadDatasets, onStart }) {
  const choice = { vehicle: null, market: null, sources: new Set(), file: null };
  let anchors = Array.from({ length: N }, () => ({})); // per stripe: {stage: {x, y (springs), h, through}}
  let launching = false;
  let frame = 0;

  root.innerHTML = `
    <form class="start-inner" novalidate>
      <svg class="flow" aria-hidden="true"></svg>
      <div class="intro">
        <p class="kicker"><span class="mark" aria-hidden="true"><i></i><i></i><i></i></span>Decision Graph</p>
        <h1 id="startTitle">New decision project</h1>
        <p class="lede">Make three choices. The agent then builds the reasoning step by step, and you
          review and steer every link of the chain.</p>
      </div>
      ${STAGES.map(rowHtml).join("")}
    </form>
    <input type="file" class="csv" accept=".csv,text/csv" hidden>`;
  const form = root.querySelector("form");
  const svg = root.querySelector(".flow");
  const rows = [...root.querySelectorAll(".row")];
  const csv = root.querySelector(".csv");

  function rowHtml(s, i) {
    let body;
    if (s.key === "brief") {
      body = `<label class="brief card" data-target>
        <span class="eyebrow">What should the agent work out?</span>
        <textarea name="goal" rows="3">${esc(DEFAULT_GOAL)}</textarea></label>`;
    } else if (s.key === "launch") {
      body = `<div class="launch">
          <label class="field"><span>Your name</span><input name="pm" autocomplete="name" required></label>
          <label class="field steps"><span>Agent steps</span><input name="steps" type="number" min="1" max="20" value="8"></label>
          <button type="submit" class="go" data-target>Start agent</button>
        </div>
        <p class="error" role="alert"></p>`;
    } else {
      body = `<div class="options" role="group" aria-label="${esc(s.title)}">${optionsHtml(s)}</div>`;
    }
    return `<div class="row" data-stage="${i}">
      <div class="label"><span class="num">${i + 1}</span><div><h2>${esc(s.title)}</h2><p>${esc(s.hint)}</p></div></div>
      <div class="body">${body}</div></div>`;
  }

  function optionsHtml(s) {
    if (!s.options.length) return `<span class="loading">loading…</span>`;
    return s.options.map((o) => `<button type="button" class="opt card" data-target data-value="${esc(o.value)}"
      aria-pressed="false"><b>${esc(o.label)}</b><span>${esc(o.sub)}</span></button>`).join("");
  }

  // ---- state -------------------------------------------------------------

  const answered = (s) => {
    const key = STAGES[s].key;
    if (key === "sources") return choice.sources.size > 0;
    if (key === "brief") return true;
    if (key === "launch") return launching;
    return choice[key] !== null;
  };

  /** Stages shown: everything up to and including the first open choice. */
  function visibleStages() {
    const vis = [];
    for (let s = 0; s < STAGES.length; s++) {
      if (!targetsOf(s).length) break; // e.g. sources still loading
      vis.push(s);
      if (!answered(s)) break;
    }
    return vis;
  }

  /** The cards the stripes flow into at stage s: the picked ones, or all options while open. */
  function targetsOf(s) {
    const all = [...rows[s].querySelectorAll("[data-target]")];
    const picked = all.filter((el) => el.classList.contains("on"));
    return picked.length ? picked : all;
  }

  function pick(s, value) {
    const st = STAGES[s];
    if (st.multi) {
      if (value === UPLOAD && !choice.sources.has(UPLOAD)) { csv.click(); return; } // picked once a file is chosen
      if (choice.sources.has(value)) choice.sources.delete(value); else choice.sources.add(value);
      if (value === UPLOAD) choice.file = null;
    } else {
      choice[st.key] = value;
    }
    update(s);
  }

  /** Re-mark the options, reveal what's next and send the stripes there. */
  function update(changed = -1) {
    const before = visibleStages().length;
    STAGES.forEach((st, s) => {
      if (!st.options) return;
      const on = (v) => (st.multi ? choice.sources.has(v) : choice[st.key] === v);
      for (const b of rows[s].querySelectorAll(".opt")) {
        b.classList.toggle("on", on(b.dataset.value));
        b.setAttribute("aria-pressed", String(on(b.dataset.value)));
        b.classList.toggle("off", answered(s) && !on(b.dataset.value));
      }
    });
    const upload = root.querySelector(`.opt[data-value="${UPLOAD}"] span`);
    if (upload) upload.textContent = choice.file ? choice.file.name : "upload a file";
    const vis = visibleStages();
    rows.forEach((r, s) => {
      const shown = vis.includes(s);
      r.classList.toggle("shown", shown);
      r.inert = !shown;
    });
    route();
    // a newly opened row scrolls into view (the brief opens together with the Start row)
    if (changed >= 0 && vis.length > before) {
      const next = rows[vis.at(-1)];
      setTimeout(() => next.scrollIntoView({ behavior: reducedMotion() ? "auto" : "smooth", block: "nearest" }), 120);
    }
  }

  // ---- geometry + springs ------------------------------------------------

  /** Position of el inside the form, ignoring transforms (rows slide in while the stripes aim at them). */
  function box(el) {
    let x = 0, y = 0;
    for (let e = el; e && e !== form; e = e.offsetParent) { x += e.offsetLeft; y += e.offsetTop; }
    return { cx: x + el.offsetWidth / 2, top: y, h: el.offsetHeight };
  }

  function originX() {
    return box(rows[0].querySelector(".body")).cx;
  }

  const spring = (v) => ({ v, vel: 0, t: v });

  /** Set every stripe's target at every visible stage; new stages grow out of the previous one. */
  function route() {
    svg.setAttribute("width", form.scrollWidth);
    svg.setAttribute("height", form.scrollHeight);
    const vis = visibleStages();
    const ox = originX();
    for (let i = 0; i < N; i++) {
      const next = {};
      let exit = { x: ox + (i - 1) * W, y: 0 };
      for (const s of vis) {
        const T = targetsOf(s);
        const t = i % T.length;
        const group = [...Array(N).keys()].filter((j) => j % T.length === t); // stripes sharing this card
        const b = box(T[t]);
        const x = b.cx + (group.indexOf(i) - (group.length - 1) / 2) * W;
        const a = anchors[i][s] ?? { x: spring(exit.x), y: spring(exit.y) }; // grow from where the stripe is
        a.x.t = x; a.y.t = b.top; a.h = b.h; a.through = answered(s);
        next[s] = a;
        exit = { x: a.x.v, y: a.y.v + a.h };
      }
      if (launching) { // the bundle shoots on down, past the bottom of the page
        const a = anchors[i].tail ?? { x: spring(exit.x), y: spring(exit.y) };
        a.x.t = exit.x; a.y.t = form.scrollHeight + 400; a.h = 0; a.through = false;
        next.tail = a;
      }
      anchors[i] = next;
    }
    kick();
  }

  function kick() {
    if (reducedMotion()) {
      for (const a of anchors.flatMap(Object.values)) { a.x.v = a.x.t; a.y.v = a.y.t; a.x.vel = a.y.vel = 0; }
      draw();
      return;
    }
    if (frame) return;
    let last = performance.now();
    const tick = (now) => {
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;
      let moving = false;
      for (const a of anchors.flatMap(Object.values)) moving = step(a.x, dt) | step(a.y, dt) || moving;
      draw();
      frame = moving ? requestAnimationFrame(tick) : 0;
    };
    frame = requestAnimationFrame(tick);
  }

  /** One spring step, in small sub-steps so it stays stable; X and Y spring independently. */
  function step(s, dt) {
    const k = (2 * Math.PI / RESPONSE) ** 2;
    const c = (4 * Math.PI * DAMPING) / RESPONSE;
    for (let t = 0; t < dt; t += 1 / 240) {
      const h = Math.min(1 / 240, dt - t);
      s.vel += (-k * (s.v - s.t) - c * s.vel) * h;
      s.v += s.vel * h;
    }
    if (Math.abs(s.v - s.t) < 0.05 && Math.abs(s.vel) < 0.05) { s.v = s.t; s.vel = 0; return false; }
    return true;
  }

  /** A vertical S-curve from (px, py) into (x, y): straight down, then bend within FORK px. */
  function curve(px, py, x, y) {
    const cs = Math.max(py, y - FORK);
    const k = (y - cs) / 2;
    return `${cs > py ? `L${px},${cs}` : ""}C${px},${cs + k} ${x},${y - k} ${x},${y}`;
  }

  function draw() {
    const vis = visibleStages();
    const ox = originX();
    const paths = [];
    const exits = []; // per stage: where the bundle leaves it (center), for the ghost lines
    let prev = { x: ox, y: 0 };
    for (const s of vis) {
      const as = anchors.map((a) => a[s]).filter(Boolean);
      if (!as.length) break;
      exits[s] = prev;
      prev = { x: as.reduce((t, a) => t + a.x.v, 0) / as.length, y: Math.max(...as.map((a) => a.y.v + a.h)) };
    }
    // thin grey lines to the options that aren't picked keep them part of the flow (and clickable)
    for (const s of vis) {
      if (!STAGES[s].options || !exits[s]) continue;
      const T = targetsOf(s);
      for (const el of rows[s].querySelectorAll(".opt")) {
        if (T.includes(el)) continue;
        const b = box(el);
        paths.push(`<path class="ghost" d="M${exits[s].x},${exits[s].y}${curve(exits[s].x, exits[s].y, b.cx, b.top)}"/>`);
      }
    }
    for (let i = 0; i < N; i++) {
      let px = ox + (i - 1) * W, py = 0;
      let d = `M${px},${py}`;
      for (const key of [...vis, "tail"]) {
        const a = anchors[i][key];
        if (!a) continue;
        d += curve(px, py, a.x.v, a.y.v);
        if (!a.through) { d += `l0,2`; break; } // ends tucked under the card it points at
        d += `L${a.x.v},${a.y.v + a.h}`;
        px = a.x.v; py = a.y.v + a.h;
      }
      paths.push(`<path class="stripe s${i}" d="${d}"/>`);
    }
    svg.innerHTML = paths.join("");
  }

  // ---- events ------------------------------------------------------------

  form.addEventListener("click", (ev) => {
    const b = ev.target.closest(".opt");
    if (!b) return;
    pick(Number(b.closest(".row").dataset.stage), b.dataset.value);
  });
  csv.addEventListener("change", () => {
    const file = csv.files[0];
    csv.value = ""; // the same file can be picked again
    if (!file) return;
    choice.file = file;
    choice.sources.add(UPLOAD);
    update(2);
  });
  form.addEventListener("submit", async (ev) => {
    ev.preventDefault();
    if (launching) return;
    const err = root.querySelector(".error");
    const name = form.pm.value.trim();
    const goal = form.goal.value.trim();
    err.textContent = !name ? "Enter your name: every step you take is recorded under it."
      : !goal ? "Write what the agent should work out." : "";
    if (err.textContent) { (name ? form.goal : form.pm).focus(); return; }
    const go = root.querySelector(".go");
    launching = true;
    go.disabled = true;
    go.textContent = "Starting…";
    update();
    try {
      await onStart({
        vehicle: choice.vehicle, market: choice.market, goal, name,
        datasets: [...choice.sources].filter((v) => v !== UPLOAD), file: choice.file,
        steps: Math.min(20, Math.max(1, Number(form.steps.value) || 8)),
      });
      launching = false;
      leave();
    } catch (e) {
      launching = false;
      err.textContent = e.message;
      go.disabled = false;
      go.textContent = "Start agent";
      update();
    }
  });
  new ResizeObserver(() => { if (!root.hidden) route(); }).observe(form);

  // the rest of the page is behind the start screen: keep it out of the tab order
  const setBackdropInert = (on) => {
    for (const el of document.body.children) if (el !== root) el.inert = on;
  };

  function leave() {
    root.classList.add("leaving");
    setTimeout(() => { root.hidden = true; root.classList.remove("leaving"); setBackdropInert(false); },
      reducedMotion() ? 0 : 450);
  }

  let loaded = false;
  async function show({ name = "" } = {}) {
    if (!root.hidden) return;
    root.hidden = false;
    setBackdropInert(true);
    if (name && !form.pm.value) form.pm.value = name;
    anchors = Array.from({ length: N }, () => ({})); // stripes grow in from the top
    update();
    if (loaded) return;
    loaded = true;
    const datasets = await loadDatasets();
    STAGES[2].options = [
      ...datasets.map((d) => ({ value: d.name, label: d.name.replace(/\.csv$/i, "").replace(/[_-]+/g, " "), sub: `${d.rows} rows` })),
      { value: UPLOAD, label: "Your CSV", sub: "upload a file" },
    ];
    rows[2].querySelector(".options").innerHTML = optionsHtml(STAGES[2]);
    update();
  }

  return {
    show,
    hide() { if (!launching && !root.hidden) { root.hidden = true; setBackdropInert(false); } },
    get launching() { return launching; },
  };
}

/* Start screen: M stripes flowing like a Sankey diagram on warm paper (see start.js). */

/* BMW's brand face is licensed, so it isn't shipped here: it's used when installed on the machine
   or when its files are put in gui/fonts/ (gitignored); otherwise the system font (SF on a Mac). */
@font-face { font-family: "BMW Type Next"; font-weight: 300; font-display: swap;
  src: local("BMW Type Next Latin Light"), local("BMWTypeNextLatin-Light"), url("fonts/BMWTypeNextLatin-Light.woff2") format("woff2"); }
@font-face { font-family: "BMW Type Next"; font-weight: 400; font-display: swap;
  src: local("BMW Type Next Latin"), local("BMWTypeNextLatin-Regular"), url("fonts/BMWTypeNextLatin-Regular.woff2") format("woff2"); }
@font-face { font-family: "BMW Type Next"; font-weight: 700; font-display: swap;
  src: local("BMW Type Next Latin Bold"), local("BMWTypeNextLatin-Bold"), url("fonts/BMWTypeNextLatin-Bold.woff2") format("woff2"); }

.start {
  --paper: #f4f3ef; --ink: #111111; --muted: #77746c; --hair: #d9d6ce; --ghost: #c9c5bb;
  --m-light: #1ea7e8; --m-dark: #1d2a8c; --m-red: #e4161f;
  --type: "BMW Type Next", system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;
  position: fixed; inset: 0; z-index: 50; overflow-y: auto; overscroll-behavior: contain;
  background: var(--paper); color: var(--ink); font-family: var(--type);
  -webkit-font-smoothing: antialiased;
  transition: opacity 450ms cubic-bezier(.2, .8, .2, 1), transform 450ms cubic-bezier(.2, .8, .2, 1), filter 450ms;
}
.start[hidden] { display: none; }
.start.leaving { opacity: 0; transform: scale(1.015); filter: blur(6px); pointer-events: none; }

.start-inner {
  position: relative; max-width: 1160px; margin: 0 auto; padding: 0 40px 35vh;
  display: grid; grid-template-columns: 280px minmax(0, 1fr); column-gap: 48px;
}
.flow { position: absolute; left: 0; top: 0; overflow: visible; pointer-events: none; }
.flow .stripe { fill: none; stroke-width: 10; stroke-linecap: butt; stroke-linejoin: round; }
.flow .s0 { stroke: var(--m-light); } .flow .s1 { stroke: var(--m-dark); } .flow .s2 { stroke: var(--m-red); }
.flow .ghost { fill: none; stroke: var(--ghost); stroke-width: 1.5; }

/* ---- intro: editorial title block between hairlines (left), the stripes run down beside it */
.intro { grid-column: 1; padding: 56px 0 8px; }
.kicker { display: flex; align-items: center; gap: 10px; margin: 0; padding-bottom: 14px; border-bottom: 1px solid var(--ink);
  font-size: 12px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
.mark { display: inline-flex; height: 14px; transform: skewX(-20deg); }
.mark i { width: 4px; } .mark i:nth-child(1) { background: var(--m-light); }
.mark i:nth-child(2) { background: var(--m-dark); } .mark i:nth-child(3) { background: var(--m-red); }
.start h1 { margin: 22px 0 18px; font-size: 44px; font-weight: 300; line-height: 1.04; letter-spacing: -.025em; }
.lede { margin: 0; padding-top: 14px; border-top: 1px solid var(--hair); font-size: 14px; line-height: 1.55; color: var(--muted); }

/* ---- rows: the label sits left, its choice sits on the stripes' path (right) */
.row { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; padding-top: 96px; /* = FORK in start.js */ }
.row:not(.shown) { opacity: 0; transform: translateY(14px); visibility: hidden; }
.row.shown { transition: opacity 500ms cubic-bezier(.2, .8, .2, 1) 140ms, transform 500ms cubic-bezier(.2, .8, .2, 1) 140ms; }
.label { display: flex; gap: 12px; align-items: flex-start; }
.num { flex: none; display: grid; place-items: center; width: 22px; height: 22px; margin-top: 2px; border-radius: 50%;
  background: var(--ink); color: var(--paper); font-size: 12px; font-weight: 700; }
.label h2 { margin: 0; font-size: 17px; font-weight: 700; letter-spacing: -.01em; line-height: 1.3; }
.label p { margin: 2px 0 0; font-size: 13px; line-height: 1.45; color: var(--muted); }
.body { position: relative; display: flex; flex-direction: column; align-items: center; min-width: 0; }

/* cards sit above the stripes and hide them where they flow through */
.card { position: relative; z-index: 1; background: var(--paper); }
.options { display: flex; flex-wrap: wrap; justify-content: center; gap: 16px 56px; }
.opt {
  min-width: 150px; padding: 12px 18px 11px; border: 0; border-top: 2px solid var(--ink); border-radius: 0;
  font: inherit; color: var(--ink); text-align: center; cursor: pointer;
  display: flex; flex-direction: column; gap: 1px;
  transition: background-color 180ms ease, color 180ms ease, transform 100ms ease-out, opacity 180ms ease;
}
.opt b { font-size: 15px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; }
.opt span { font-size: 12px; color: var(--muted); letter-spacing: .01em; }
.opt:hover { background: #e9e7e1; }
.opt:active { transform: scale(.97); }
.opt.on { background: var(--ink); color: #fff; border-top-color: var(--ink); }
.opt.on span { color: #b9b6ae; }
.opt.off { color: var(--muted); border-top-color: var(--ghost); }
.opt.off:hover { color: var(--ink); }
.opt:focus-visible, .go:focus-visible, .brief textarea:focus-visible, .field input:focus-visible {
  outline: 2px solid var(--m-light); outline-offset: 3px;
}
.loading { color: var(--muted); font-size: 13px; }

.brief { display: block; width: min(560px, 100%); padding: 14px 18px 12px; border-top: 2px solid var(--ink); }
.eyebrow { display: block; font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--muted); }
.brief textarea { display: block; width: 100%; margin-top: 6px; padding: 0; border: 0; resize: vertical; background: none;
  font: 300 19px/1.4 var(--type); letter-spacing: -.01em; color: var(--ink); }
.brief textarea:focus { outline: none; }

.launch { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: center; gap: 16px 28px; }
.field { display: flex; flex-direction: column; gap: 4px; position: relative; z-index: 1; }
.field span { font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--muted); }
.field input { width: 180px; padding: 6px 0; border: 0; border-bottom: 1px solid var(--ink); border-radius: 0; background: none;
  font: 400 16px var(--type); color: var(--ink); }
.field.steps input { width: 72px; }
.field input:focus { outline: none; border-bottom-color: var(--m-light); }
.go {
  position: relative; z-index: 1; min-width: 180px; padding: 15px 28px; border: 0; border-radius: 0;
  background: var(--ink); color: #fff; font: 700 14px var(--type); letter-spacing: .08em; text-transform: uppercase; cursor: pointer;
  transition: transform 100ms ease-out, background-color 180ms ease;
}
.go:hover { background: #2a2a2a; }
.go:active { transform: scale(.97); }
.go:disabled { cursor: progress; }
.error { min-height: 1.4em; margin: 14px 0 0; font-size: 13px; color: var(--m-red); text-align: center; }

@media (max-width: 800px) {
  .start-inner { grid-template-columns: minmax(0, 1fr); padding: 0 16px 35vh; }
  .row { grid-template-columns: minmax(0, 1fr); row-gap: 14px; }
  .intro { padding-top: 32px; }
  .start h1 { font-size: 34px; }
  .options { gap: 12px 16px; }
  .opt { min-width: 120px; }
}
@media (prefers-reduced-motion: reduce) {
  .start, .row.shown, .opt, .go { transition: opacity 200ms ease; }
  .row:not(.shown) { transform: none; }
  .start.leaving { transform: none; filter: none; }
}

input.new_string:
renderGraph();
if (!graph.nodes.length || forceStart) guard(start.show)({ name: $("#pm").value });
else start.hide();
renderStats();

input.old_string:
async function renderStart() {
  if (renderStart.done) return;
  renderStart.done = true;
  $("#startPm").value = $("#pm").value;
  const datasets = await api("/datasets");
  $("#startSources").innerHTML = datasets.map((d) => `
